using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;using System.Threading.Tasks;using V15Voice;
public static class AiTimelineUiTests {
 static int n;static object F(object o,string k){return o.GetType().GetField(k,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object C(object o,string k,params object[] a){return o.GetType().GetMethod(k,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(bool b,string name){if(!b)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}static void Capture(Form f,string name){using(var b=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.Location,Point.Empty,f.Size);b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation",name+".png"));}}
 sealed class E:KokoroEngine{public override void CheckFiles(){}public override Wave Generate(string text,double speed,string output){int words=System.Text.RegularExpressions.Regex.Matches(text,@"\b\w+\b").Count;return new Wave{Rate=24000,Samples=Enumerable.Range(0,words*7200).Select(i=>(short)(5000*Math.Sin(i*.06))).ToArray()};}}
 sealed class W:ITextRewriter{public string Rewrite(string prompt,Func<bool> cancel,Action<string> action){return "{\"cues\":[{\"id\":1,\"text\":\"John could not believe the door had finally opened.\"}]}";}}
 [STAThread]public static int Main(){Application.EnableVisualStyles();var f=new MainForm();try{f.Show();Application.DoEvents();var mode=(ComboBox)F(f,"aiMode");Check(mode.Items.Count==3&&mode.SelectedIndex==0,"Three AI modes exist and default off");mode.SelectedIndex=2;((CheckBox)F(f,"aiFixShort")).Checked=false;var saved=(VoiceSettings)C(f,"CaptureSettings");Check(saved.AiMode==2&&!saved.AiFixShort,"AI settings captured for Studio/queue and persistence");mode.SelectedIndex=0;C(f,"Apply",saved);Check(mode.SelectedIndex==2&&!((CheckBox)F(f,"aiFixShort")).Checked,"Preset/session restore keeps AI mode and short-cue policy");C(f,"SetBusy",true);Check(!mode.Enabled,"AI settings cannot change during render");C(f,"SetBusy",false);Check(mode.Enabled,"AI settings unlock after render");
  string folder=Path.Combine(Path.GetTempPath(),"V15 AI UI "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"story.srt");var cues=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,300\nJohn was standing there for a very long time because the door had finally opened.\n\n2\n00:00:03,300 --> 00:00:06,600\nThis detail changes the whole story for everyone.\n");File.WriteAllText(file,Scripts.ToSrt(cues));string hash=StateFiles.Hash(file);var settings=new VoiceSettings{Mode=0,Slow=false,Breathing=2,Normalize=false,Device="cpu"};var p=AiRepairSession.Open(file,cues,folder,settings,false);Func<string,KokoroEngine> factory=role=>new E{Root=folder,VoiceName="UI voice "+role};AiTimeline.Run(p,new W(),factory,()=>false,(i,m)=>{},false);
  using(var d=new AiTimelineDialog(folder,p,factory,new W())){d.Show(f);d.Location=Point.Empty;Application.DoEvents();var grid=(DataGridView)F(d,"grid");Check(grid.RowCount==2&&((TextBox)F(d,"original")).ReadOnly&&((TextBox)F(d,"proposed")).ReadOnly,"Review table and read-only before/after text show actual session");Check(((TextBox)F(d,"proposed")).Text.Contains("could not believe"),"Actual candidate wording is visible before approval");C(d,"Accept",false);Check(p.Rows[0].Chosen!=null,"Approve selected row marks only measured valid proposal");C(d,"Undo");Check(p.Rows[0].Chosen==null&&p.Effective()[0].Text==cues[0].Text,"Undo returns exact original sentence");((CheckBox)F(d,"onlyProblems")).Checked=true;Check(grid.RowCount==1,"Problem filter hides passing rows");((CheckBox)F(d,"onlyProblems")).Checked=false;C(d,"Accept",true);Check(p.Rows.Count(r=>r.Chosen!=null)==1,"Approve-all affects valid proposals only");
   foreach(var size in new[]{new Size(1260,860),new Size(1080,740)}){d.Size=size;Application.DoEvents();Check(((TextBox)F(d,"original")).ClientSize.Height>=100&&grid.ClientSize.Height>=120,"Review remains usable at "+size);Capture(d,"ai-review-"+size.Width);}
   C(d,"Busy",true);Check(!grid.Enabled&&((Button)F(d,"stop")).Enabled,"Busy review locks edits and leaves Stop enabled");C(d,"Busy",false);C(d,"Apply",false);Check(d.Applied&&!d.RenderAfterApply,"Applying into script is separate from render action");}
  Check(StateFiles.Hash(file)==hash,"Review actions preserve source file bytes");Check(((TabControl)F(f,"tabs")).TabCount==7,"Seven main tabs retained without restored video editor");Console.WriteLine("TOTAL AI UI "+n+" passed.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}finally{f.Close();}}
}
